<template><CrudShell title="Quản lý customer" :loading="loading" :error="error" @create="openCreate" @reload="load"><template #form v-if="editing"><form class="grid gap-3 rounded-3xl border bg-white p-4 md:grid-cols-3" @submit.prevent="save"><input v-model="form.fullName" class="rounded-xl border p-3" placeholder="Full name"><input v-model="form.email" class="rounded-xl border p-3" placeholder="Email"><input v-model="form.phone" class="rounded-xl border p-3" placeholder="Phone"><select v-model="form.status" class="rounded-xl border p-3"><option>ACTIVE</option><option>INACTIVE</option></select><div class="flex gap-2 md:col-span-3"><button class="rounded-xl bg-slate-950 px-4 py-2 font-bold text-white">Save</button><button type="button" class="rounded-xl border px-4 py-2" @click="editing = null">Cancel</button></div></form></template><table class="w-full text-left text-sm"><thead><tr class="border-b"><th class="p-3">Name</th><th>Email</th><th>Phone</th><th>Status</th><th></th></tr></thead><tbody><tr v-for="row in rows" :key="row.id" class="border-b"><td class="p-3 font-bold">{{ row.fullName }}</td><td>{{ row.email }}</td><td>{{ row.phone }}</td><td>{{ row.status }}</td><td class="space-x-2 text-right"><button class="font-bold" @click="openEdit(row)">Edit</button><button class="font-bold text-red-600" @click="remove(row.id)">Delete</button></td></tr></tbody></table></CrudShell></template>
<script setup lang="ts">
import { onMounted, reactive, ref } from 'vue'; import CrudShell from '@/pages/admin/CrudShell.vue'; import { customerApi } from '@/modules/customer/api'; import { getErrorMessage } from '@/modules/shared/hooks'; import type { Customer, CustomerPayload } from '@/modules/customer/types'
const rows = ref<Customer[]>([]); const loading = ref(false); const error = ref(''); const editing = ref<Customer | 'new' | null>(null); const form = reactive<CustomerPayload>({ fullName: '', email: '', phone: '', status: 'ACTIVE' })
function fill(r?: Customer) { Object.assign(form, { fullName: r?.fullName || '', email: r?.email || '', phone: r?.phone || '', status: r?.status || 'ACTIVE' }) } function openCreate() { editing.value = 'new'; fill() } function openEdit(r: Customer) { editing.value = r; fill(r) } async function load() { loading.value = true; try { rows.value = (await customerApi.list({ limit: 50 })).items } catch (e) { error.value = getErrorMessage(e) } finally { loading.value = false } } async function save() { try { if (editing.value === 'new') await customerApi.create(form); else if (editing.value) await customerApi.update(editing.value.id, form); editing.value = null; await load() } catch (e) { error.value = getErrorMessage(e) } } async function remove(id: string) { if (!confirm('Delete customer?')) return; await customerApi.remove(id); await load() } onMounted(load)
</script>
